const registros = $input.all().map(item => item.json);

const produtos = registros.filter(p => p.estoque_atual !== undefined);
const vendas = registros.filter(v => v.venda_id !== undefined);

const diasHistorico = 30;
const diasSeguranca = 3;
const diasCobertura = 30;

const resultados = produtos.map(produto => {
  const totalVendido = vendas
    .filter(venda => venda.produto_id === produto.produto_id)
    .reduce((total, venda) => total + Number(venda.quantidade || 0), 0);

  const estoqueAtual = Number(produto.estoque_atual);
  const prazoReposicao = Number(produto.prazo_reposicao_dias);

  const consumoDiario = totalVendido / diasHistorico;
  const pontoReposicao = consumoDiario * (prazoReposicao + diasSeguranca);
  const estoqueDesejado = consumoDiario * diasCobertura;

  const precisaRepor = estoqueAtual <= pontoReposicao;

  const quantidadeRecomendada = precisaRepor
    ? Math.max(0, Math.ceil(estoqueDesejado - estoqueAtual))
    : 0;

  return {
    produto_id: produto.produto_id,
    produto: produto.produto,
    estoque_atual: estoqueAtual,
    total_vendido_30_dias: totalVendido,
    consumo_diario: Number(consumoDiario.toFixed(2)),
    ponto_reposicao: Number(pontoReposicao.toFixed(2)),
    precisa_repor: precisaRepor,
    quantidade_recomendada: quantidadeRecomendada,
    status: precisaRepor
      ? "REPOSICAO_NECESSARIA"
      : "ESTOQUE_NORMAL"
  };
});

return resultados;

const produtos = $input.all().map(item => item.json);

const precisamRepor = produtos.filter(
  produto => produto.precisa_repor === true
);

const estoqueNormal = produtos.filter(
  produto => produto.precisa_repor === false
);

const totalRecomendado = precisamRepor.reduce(
  (total, produto) =>
    total + Number(produto.quantidade_recomendada),
  0
);

let mensagem = "📦 RELATÓRIO DE ESTOQUE\n\n";

mensagem += `Produtos analisados: ${produtos.length}\n`;
mensagem += `Estoque normal: ${estoqueNormal.length}\n`;
mensagem += `Precisam de reposição: ${precisamRepor.length}\n\n`;

if (precisamRepor.length > 0) {
  mensagem += "⚠️ REPOSIÇÃO RECOMENDADA\n\n";

  precisamRepor.forEach(produto => {
    mensagem += `• ${produto.produto}\n`;
    mensagem += `  Estoque atual: ${produto.estoque_atual}\n`;
    mensagem += `  Quantidade sugerida: ${produto.quantidade_recomendada} unidades\n\n`;
  });
} else {
  mensagem += "✅ Nenhum produto precisa de reposição.\n\n";
}

mensagem += `Total recomendado: ${totalRecomendado} unidades\n\n`;
mensagem += "Atenção: recomendação sujeita à aprovação humana. Nenhuma compra foi realizada.";

return [
  {
    json: {
      mensagem,
      total_produtos: produtos.length,
      produtos_para_reposicao: precisamRepor.length,
      quantidade_total_recomendada: totalRecomendado
    }
  }
];
